var videoWrapper=document.querySelectorAll(".video__wrapper");videoWrapper.forEach(e=>{var a=e.querySelector(".play"),r=e.querySelector("video");a.addEventListener("click",function(e){e.preventDefault(),r.play()}),r.addEventListener("play",function(e){a.classList.add("play--hide")}),r.addEventListener("click",function(e){r.paused?r.play():(r.pause(),a.classList.remove("play--hide"))})});